// Compute the last completed Mon-Sun week and the current month window, at run time.
// 'Last completed week' = the most recent full Mon-Sun week that has already ended
// (e.g. running Monday 07:00 always reports on the week that just finished).
const now = new Date();
const dow = now.getUTCDay(); // 0=Sun,1=Mon,...6=Sat
const daysSinceMonday = (dow + 6) % 7;
const thisMonday = new Date(now); thisMonday.setUTCHours(0,0,0,0); thisMonday.setUTCDate(now.getUTCDate() - daysSinceMonday);
const lastMonday = new Date(thisMonday); lastMonday.setUTCDate(thisMonday.getUTCDate() - 7);

function iso(d){ return d.toISOString().slice(0,10); }

const monthNum = lastMonday.getUTCMonth() + 1; // month option keyed off the reported week's Monday
const weekMonth = lastMonday.getUTCFullYear() + '-' + String(monthNum).padStart(2, '0');
const quarterNum = Math.ceil(monthNum / 3);
const weekQuarter = lastMonday.getUTCFullYear() + '-Q' + quarterNum;

const curMonthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
const curMonthStr = now.getUTCFullYear() + '-' + String(now.getUTCMonth() + 1).padStart(2, '0');

return [{ json: {
  lastMondayISO: iso(lastMonday),
  thisMondayISO: iso(thisMonday),
  weekMonth,
  weekQuarter,
  curMonthStartISO: iso(curMonthStart),
  curMonthStr,
  todayISO: iso(now)
}}];

// Un-freeze + self-populate the 4 time-based Priority Tracker rows (G-B, 2026-07-10).
// Scope is deliberately narrow: New Leads / Alignment Calls / Closes per Week / Lead Gen per Month.
// Membership Revenue, Paid Members, Proximity Members are NOT touched here -- those were
// hand-corrected in Task 1/2 (see PRODUCTION_GROUND_TRUTH.md) and must not be re-patched
// by this workflow, or it would silently re-fabricate numbers that were just fixed.

const win = $('Compute Date Windows').first().json;

const oppsBody = $('GET Opportunities (last wk)').first().json;
const newLeads = (oppsBody.records || []).length;

const apptBody = $('GET Raw Appointments (last wk)').first().json;
const alignmentCalls = (apptBody.records || []).filter((r) => {
  const title = String((r.fields && r.fields['Calender Title']) || '').toLowerCase();
  return title.includes('alignment');
}).length;

const ga4Body = $('GET GA4 Sitewide (MTD)').first().json;
const ga4Row = (ga4Body.rows && ga4Body.rows[0]) || null;
const mtdVisitors = ga4Row ? Number((ga4Row.metricValues && ga4Row.metricValues[0] && ga4Row.metricValues[0].value) || 0) : 0;

return [
  { json: { recordId: 'EXAMPLE_AIRTABLE_ID_7099F5E6D1', fields: {
      Actual: newLeads, Week: win.lastMondayISO, Month: win.weekMonth, Quarter: win.weekQuarter
  }}},
  { json: { recordId: 'EXAMPLE_AIRTABLE_ID_BD4F6886D4', fields: {
      Actual: alignmentCalls, Week: win.lastMondayISO, Month: win.weekMonth, Quarter: win.weekQuarter
  }}},
  { json: { recordId: 'EXAMPLE_AIRTABLE_ID_B3FCAA6C6E', fields: {
      Week: win.lastMondayISO, Month: win.weekMonth, Quarter: win.weekQuarter
      // Actual intentionally omitted -- shell, gated on the still-unverified paid roster
  }}},
  { json: { recordId: 'EXAMPLE_AIRTABLE_ID_512FDB8AE2', fields: {
      Actual: mtdVisitors, Month: win.curMonthStr
  }}}
];

// Extends G-B to also feed Sales Engine's weekly activity fields (2026-07-10),
// retiring "SAMPLE . Weekly Rollup -> Sales Engine", which had 3 stacked bugs:
//   1. Date-window bug -- it measured the week AHEAD (0 hours elapsed at run time),
//      not the week that just ended, so every automated run read near-zero.
//   2. Upsert-key bug -- matched on Airtable's own record "id", which the code never
//      output, so it could never match an existing week's row.
//   3. Closes were bucketed off Win Basis values ("catalyst_paid" etc.) that DO NOT
//      EXIST on the live field (real options: open/lost/free_member/proximity_excluded/
//      ghl_status_won/type_paid_stage) -- structurally guaranteed to always read 0.
// This node reuses the already-correct last-completed-week window from Compute Date
// Windows (fixes #1) and upserts matched on "Week" (fixes #2). It deliberately does NOT
// write any close-related field (Catalyst/Core/Circle/Capital Engine/Nexus Total Closed,
// or the close-rate formulas that depend on them) -- that needs a live tier signal that
// doesn't exist yet (same gap as Task 2's paid-roster fix). Leaving those blank is honest,
// not a regression -- do NOT invent a bucketing rule to fill them.

function norm(v){ return (v == null ? '' : String(v)).toLowerCase().trim(); }
function repBucket(name){
  const n = norm(name);
  if (n.includes('john')) return 'John';
  if (n.includes('heather')) return 'Heather';
  if (n.includes('mitchell')) return 'Mitchell';
  if (n.includes('katie')) return 'Katie';
  return null;
}
function isCancelled(s){
  const n = norm(s);
  return n.includes('cancel') || n.includes('noshow') || n.includes('no show') || n.includes('invalid');
}
function isConducted(s){
  const n = norm(s);
  return n.includes('show') && !n.includes('noshow') && !n.includes('no show');
}

const win = $('Compute Date Windows').first().json;

const oppsBody = $('GET Opportunities (last wk)').first().json;
const newLeads = (oppsBody.records || []).length;

const apptBody = $('GET Raw Appointments (last wk)').first().json;
const appts = apptBody.records || [];

let booked = 0, conducted = 0;
const byRep = { John: 0, Heather: 0, Mitchell: 0, Katie: 0 };

for (const r of appts) {
  const f = r.fields || {};
  if (!norm(f['Calender Title']).includes('alignment')) continue;
  const status = f['Appointment Status'];
  if (isCancelled(status)) continue;
  booked++;
  const rep = repBucket(f['Assigned User']);
  if (rep) byRep[rep]++;
  if (isConducted(status)) conducted++;
}

return [{ json: {
  'Week': win.lastMondayISO,
  'New Leads': newLeads,
  'Alignment Calls Booked': booked,
  'Alignment Calls Conducted': conducted,
  'Alignment Calls by John': byRep.John,
  'Alignment Calls by Heather': byRep.Heather,
  'Alignment Calls by Mitchell': byRep.Mitchell,
  'Alignment Calls by Katie': byRep.Katie
}}];

// Explicit find-then-write instead of n8n's native "upsert" operation. The native upsert
// (matchingColumns on a date-type field) was tried first and produced 2 duplicate rows for
// the same Week on a single import+run -- its match logic didn't reliably find its own
// freshly-written row. This GET-then-decide-then-PATCH/POST shape is the same pattern
// already proven reliable everywhere else in this workflow (CEO Command Center writes).

const found = $input.first().json;
const row = $('Compute Sales Engine Row').first().json;
const fields = { ...row };

const base = 'https://api.airtable.com/v0/EXAMPLE_RESOURCE_ID_3584EBCAFD/EXAMPLE_RESOURCE_ID_4E0F029915';
const existing = (found.records || [])[0];

if (existing) {
  return [{ json: { method: 'PATCH', url: `${base}/${existing.id}`, fields } }];
}
return [{ json: { method: 'POST', url: base, fields } }];

// Pooled Overall Close Rate (Task 5 CORRECTION, 2026-07-13 -- supersedes the earlier
// Membership-Conversion-field ADD-ON, which is now dead/orphaned, see PRODUCTION_GROUND_TRUTH).
// TRUE overall close rate = cumulative Paid Members / cumulative alignment-calls-conducted-or-
// beyond (Unified Stage in Alignment Call Conducted/Pulse Check Booked/Pulse Check Conducted/
// Closed Won/Closed Lost -- live snapshot 2026-07-13 = 21). This is a POOLED ratio, not an
// average of weekly rates -- the next node writes it to exactly ONE hardcoded, permanently-fixed
// Sales Engine row (never the rolling "current week" row, which changes every run) so the CEO
// tile's Average-summary resolves to this one value instead of blending multiple weeks together.
// Paid Members is read live from Membership Conversion but NOT re-patched anywhere by this
// workflow -- it's provisional (hand-corrected in Task 2, PRODUCTION_GROUND_TRUTH SS B33) and
// this calc self-corrects automatically once the real roster/tags land there.

const oppsBody = $('GET Opportunities (Alignment+ cumulative)').first().json;
const alignmentOrBeyond = (oppsBody.records || []).length;

const mcBody = $('GET Membership Conversion (Paid Members)').first().json;
const mcRow = (mcBody.records || [])[0];
const paidMembers = mcRow ? Number(mcRow.fields['Paid Members'] || 0) : 0;

const pooledCloseRate = alignmentOrBeyond > 0 ? (paidMembers / alignmentOrBeyond) : null;

return [{ json: {
  paidMembers,
  alignmentOrBeyond,
  pooledCloseRate
}}];
